<?php require_once __DIR__.'/../includes/config.php';require_admin();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$status=$_POST['status']??'';$note=trim($_POST['note']??'');if(in_array($status,['Submitted','Under Review','Approved','Rejected'],true)){$s=$pdo->prepare('UPDATE applications SET status=?,admin_note=? WHERE id=?');$s->execute([$status,$note,$id]);header('Location: dashboard.php?updated=1');exit;}}$apps=$pdo->query('SELECT a.*,u.full_name,u.email FROM applications a JOIN users u ON u.id=a.user_id ORDER BY a.created_at DESC')->fetchAll();?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin dashboard | Ladle Loan</title><link rel="stylesheet" href="../assets/style.css"></head><body><div class="form-wrap" style="max-width:1100px"><div class="form-card"><a href="../index.php">Ladle Loan</a><h1>Administrator dashboard</h1><p>Signed in as <?=e($_SESSION['admin_name']??'Admin')?> · <a href="../logout.php">Logout</a></p><?php if(isset($_GET['updated'])):?><div class="notice success">Application updated.</div><?php endif;?><div class="table-wrap"><table><tr><th>Applicant</th><th>Reference / Loan</th><th>Amount</th><th>Review</th></tr><?php foreach($apps as $a):?><tr><td><?=e($a['full_name'])?><br><small><?=e($a['email'])?></small></td><td><?=e($a['reference_no'])?><br><?=e($a['loan_type'])?></td><td>₹<?=number_format((float)$a['amount'],2)?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)$a['id']?>"><select name="status"><?php foreach(['Submitted','Under Review','Approved','Rejected'] as $st):?><option <?= $a['status']===$st?'selected':''?>><?=e($st)?></option><?php endforeach;?></select><input name="note" placeholder="Admin note" value="<?=e($a['admin_note']??'')?>"><button class="btn">Save</button></form></td></tr><?php endforeach;?><?php if(!$apps):?><tr><td colspan="4">No applications submitted yet.</td></tr><?php endif;?></table></div></div></div></body></html>